%-------------------------------------------------------- 1 attv_tests_attv_test
/* File:      attv_test.P
** Author(s): Baoqiu Cui
** 
** This file contains some basic tests for attributed variables.
** $Id: attv_test.P,v 1.9 2011-03-13 00:33:51 tswift Exp $
*/

:- import put_attr/3, get_attr/3, install_verify_attribute_handler/4 from machine.
:- import get_atts/2, put_atts/2 from atts.
:- import attv_unify/2 from machine.

test :-
	test_deref,
	test_update,
	test_unify,
	test_attv_interrupt,
	test_attv_disj_interrupt,
	test_implict_unify,
	test_cut1,
	test_cut2,
	writeln('PASSED attv_test!').

:- install_verify_attribute_handler(nounif,AttrVal,Targ,dummy_handler(Targ,AttrVal)).
:- install_verify_attribute_handler(unif,AttrVal,Targ,fail(Targ,AttrVal)).

fail(_,_):- fail.

dummy_handler(Value, Target) :-
	(var(Target) -> 
	    get_attr(Target, _, Atts)
	 ;  Atts = Target),
	write('Var''s attribute = '), writeln(Atts),
	write('Value = '), writeln(Value).

test_deref :-
	Y2 = Y, Y = X,
	put_attr(X, nounif,v(1)),
	put_attr(X, nounif,v(2)),
	get_attr(X, nounif, V1),
	nonvar(V1), V1 = v(2),
	get_attr(Y, nounif,V3),
	nonvar(V3), V3 = v(2),
	put_attr(X, nounif, _),
	get_attr(X, nounif, V2),
	var(V2),
	get_attr(Y, nounif, V4),
	var(V4),
	put_attr(Y2, nounif, v(3)),
	get_attr(Y2, nounif, V5),
	nonvar(V5), V5 = v(3),
	writeln('== test_deref OK').
	
test_update :-
	put_attr(X, _nounif,v(1,2,3)),
	(put_attr(X, _nounif,v(2,3,4)),
	 put_attr(X, _nounif,v(3,4,5)),
	 get_attr(X, _nounif,V),
	 nonvar(V), V = v(3,4,5),
	 writeln('== test_update 1 OK')
         ;
	 get_attr(X, _nounif,Vold ),
	 nonvar(Vold), Vold = v(1,2,3),
	 writeln('== test_update 2 OK')
	),
	fail.
test_update.

test_unify :-
	put_attr(X, nounif,v(1)),
	Y = X,	% notice the order: op2 = X
	X = Z,
	get_attr(Y, nounif,VY),
	nonvar(VY), VY = v(1),
	get_attr(Z, nounif,VZ),
	nonvar(VZ), VZ = v(1),
	writeln('== test_unify OK').

test_attv_interrupt :-
	put_attr(X, nounif,v(1)),
	Y = 5,
	Y = X,	% unify(ATTV, Y) ???
	writeln('== test_attv_interrupt OK').

test_attv_disj_interrupt :-
	put_attr(X, nounif,v(12)),
	Y = 7,
	Y = X,	% unify(ATTV, Y) ???
	(writeln(disjunct_A) ; writeln(disjunct_B)),
	writeln('== test_attv_disj_interrupt OK'),
	fail.
test_attv_disj_interrupt.

test_implict_unify :-
	put_attr(X, nounif,v(11)),
	put_attr(Y, nounif,v(22)),
	handle_interrupts([(X,a), (Y,b)]),
	X == a, Y == b,
	writeln('== test_implict_unify OK').

test_cut1 :-
	put_attr(X, unif, v(30)),
	Y = 1,
	X=Y,
	!,
	writeln('== test_cut1 FAILED').
test_cut1 :-
	writeln('== test_cut1 SUCCEEDED').

test_cut2 :-
	put_attr(X, nounif, v(30)),
	Y=2,
	p(X,Y,1,2,3,4).

p(X,X,A,B,C,D) :- !, q(A,B,C,D), writeln('== test_cut2 SUCCEEDED').
p(_,_,_,_,_,_) :- writeln('== test_cut2 FAILED').

q(1,2,3,4).

handle_interrupts([]) :- !.
handle_interrupts([(Var,Value)|Ints]) :-
	get_attr(Var, nounif, Atts),
	write('Attribute = '), writeln(Atts),
	attv_unify(Var, Value),
	handle_interrupts(Ints).

% DRIVER (appended by the vendoring, CEO-700): XSB attv_tests/test.sh runs gentest.sh attv_test "test."
xsb_nonempty_line(L) :- string_length(L, N), N > 0.
xsb_sorted_output(G) :- with_output_to(string(S), catch(ignore(G), E, print_message(error, E))), split_string(S, "\n", "", L0), include(xsb_nonempty_line, L0, L1), msort(L1, L), forall(member(X, L), (write(X), nl)).
:- initialization(xsb_sorted_output((test))).
%---------------------------------------------------- 2 attv_tests_copyterm_attv
/* File:      copyterm_attv.P
** Author(s): Baoqiu Cui, Swift
**
** $Id: copyterm_attv.P,v 1.3 2004-11-17 21:43:37 tswift Exp $
*/

:- import put_attr/3, get_attr/3 from machine.
:- import install_attribute_portray_hook/3 from machine.
:- import numbervars/1 from num_vars.
:- import copy_term_nat/2 from basics.

:- install_attribute_portray_hook(ct,Attr,portray_ct(Attr)).

portray_ct(Attr):- (numbervars(Attr),write(Attr),fail ; true).

test :-
      test_sharing,
      test_cyclic_term,
      writeln('Passed copyterm_attv test (copy_term/2)!'),
      fail.
test :-
      test_sharing_3,
      test_cyclic_term_3,
      fail.
test:- test_list,fail.
test:- test_struct,fail.
test.

test_sharing :-
	put_attr(X, ct, v(a)),
	copy_term(f(X,g(X)), T),
	T = f(Y,g(Z)),			% Y and Z are shared in T
	put_attr(Y, ct, v(b)),	% so update Y will also update Z
	get_attr(Y, ct, VY),
	get_attr(Z, ct, VZ),
	nonvar(VY), VY = v(b),
	nonvar(VZ), VZ = v(b),
	put_attr(A, ct, v(123)),	% Test shared attvs in a functor
	copy_term(f(A,A), G),
	G = f(B,C),
	put_attr(B, ct, v(456)),
	get_attr(C, ct, VC),
	nonvar(VC), VC = v(456),
	writeln('== test_sharing is OK').

test_cyclic_term :-
	put_attr(X, ct, v(Y,a)),
	put_attr(Y, ct, v(X,b)),
	copy_term(f(X,X), f(NewX1, NewX2)),
	NewX1 == NewX2,
	get_attr(NewX2, ct, VX),
	nonvar(VX), VX = v(NewY, a),
	get_attr(NewY, ct,  VY),
	nonvar(VY), VY = v(XinY, b),
	XinY == NewX1,
	writeln('== test_cyclic_term is OK').

test_sharing_3 :-
	put_attr(X, ct, v(a)),
	copy_term_nat(f(X,g(X)), T),
	T = f(Y,g(Z)),			% Y and Z are shared in T
	put_attr(Y, ct, v(b)),	% so update Y will also update Z
	get_attr(Y, ct, VY),
	get_attr(Z, ct, VZ),
	nonvar(VY), VY = v(b),
	nonvar(VZ), VZ = v(b),
	put_attr(A, ct, v(123)),	% Test shared attvs in a functor
	copy_term_nat(f(A,A), G),
	G = f(B,C),
	put_attr(B, ct, v(456)),
	get_attr(C, ct, VC),
	nonvar(VC), VC = v(456),
	writeln('== test_sharing_3 is OK').

test_cyclic_term_3 :-
	put_attr(X, ct, v(Y,a)),
	put_attr(Y, ct, v(X,b)),
	copy_term_nat(f(X,X), f(NewX1, NewX2)),
	NewX1 == NewX2,
        numbervars(f(NewX1, NewX2)),
        writeln(test_cyclic_term_3(f(NewX1, NewX2))).
%	writeln('== test_cyclic_term_3 is OK').

test_struct:- 
	put_attr(X, ct, v(a)),
%	writeln(f(X,X)),
	copy_term_nat(f(X,g(X)), T),
	numbervars(T),
	writeln(test_struct(T)).

test_list:- 
	put_attr(X, ct, v(a)),
%	writeln(f(X,X)),
	copy_term_nat(f(X,[X]), T),
	numbervars(T),
	writeln(test_list(T)).



