%----------------------------------------------------------- 102 float_tests_vac
%---------------------------------------------------------------
% General test for floating point number manipulation.
%---------------------------------------------------------------

vac(Y/M, _, _) :-
	Y =:= 94, M > 9, !.
vac(Y/M, S, Incr) :-
	write(Y/M:S),nl,
	S2 is S + Incr,
	M1 is M + 1,
	(   M1 > 12
	->  M2 = 1, Y2 is Y + 1
	;   M2 = M1, Y2 = Y
	),
	vac(Y2/M2, S2, Incr).

test :- Incr is 20.0 / 12 * 8, vac(93/06, 0.0, Incr), fail.


