%% convert 3-digit exponents digits to 2 digits for windows.
fix_float_digs(Inp,Num0,Num) :-
	float(Inp),
	append(First,[e,Sign,0,Ex2,Ex3],Num0),
	!,
	append(First,[e,Sign,Ex2,Ex3],Num).
fix_float_digs(_,Num,Num).


