		  db2(p(a,2,3)),db2(p(a,2,4)),db2(p(a,3,5)),db2(p(a,3,6)),db2(p(b,3,4)),
		  db2(p(b,2,3)),db2(p(b,2,4)),db2(p(b,3,5)),db2(p(b,3,6)),db2(p(b,3,4)),
		  db2(p(c,2,3)),db2(p(c,2,4)),db2(p(c,3,5)),db2(p(d,3,6)),db2(p(f,3,4))
		  ],
