                ''flight'': ''FLIGHTS-MARQUEE'',
                ''hotel'': ''HOTELS-MARQUEE'',
                ''car'': ''CARS-MARQUEE'',
                ''cruise'': ''CRUISES-MARQUEE'',
                ''activity'': ''ACTIVITIES-MARQUEE'',
                ''rail'': ''RAILS-MARQUEE'',
                ''domestic'': ''HOTELS-MARQUEE''
            };
            return marqueeAdMap[(route === '''') ? ''home'' : route];
        };
        require([ ''uitk'' ], function(uitk) {
