            uitk.mediaquery.register("(min-width: 321px) and (max-width: 600px)", "ads-NM");
            uitk.mediaquery.register("(max-width: 600px)", "ads-NM");
            uitk.mediaquery.register("(min-width: 601px)", "ads-NM");
