%----------------------------------------------- 191 prolog_tests_test_term_size
:- import for/3 from basics.

test:- 
    term_size([a,1,_X,f(a),1.1],S),writeln(type_test_size(S)),
    makelist(100,L),term_size(L,LN),writeln(list_size(LN)),
    makef(100,F),term_size(F,FN),writeln(functor_size(FN)).

makelist(0,[]):-!.
makelist(N,[N|T]):- 
    N1 is N - 1,
    makelist(N1,T).

makef(0,a):-!.
makef(N,f(T)):- 
    N1 is N - 1,
    makef(N1,T).

test_td(Nin,Nout):-
    makelist(Nin,L),
    term_size(L,Nout).

time(Len,Its,Time):-
    cputime(B),
    makelist(Len,L),
    cputime(A),T is A - B,writeln(maketime(T)),
    cputime(Before),
    time_1(Its,L),
    cputime(After),
    Time is After - Before.

timef(Len,Its,Time):-
    makef(Len,L),
    cputime(Before),
    time_1(Its,L),
    cputime(After),
    Time is After - Before.


time_1(Its,L):- 
    for(_I,1,Its),
    term_size(L,_),
    fail.
time_1(_Its,_L).

