%---------

test_subgoal_abstraction(N,L):- 
   abolish_all_tables,
   set_prolog_flag(max_table_subgoal_size,10),
   set_prolog_flag(max_table_subgoal_size_action,abstract),
   makelist(N,L),
   s(L).

:- table r/2.
r(N,L):- makelist(N,L).

%---------

test_answer_abstraction(N,L):- 
   abolish_all_tables,
   set_prolog_flag(max_table_answer_size,10),
   set_prolog_flag(max_table_answer_size_action,abstract),
   r(N,L).

