test_intern:- 
       catch(test_intern_1(800),error(A,context(_B,_C)),writeln(A)),
       catch(test_intern_2(1000),error(A,context(_B,_C)),writeln((test_intern_2(A)))).

test_intern_1(N):- 
       new_trie(Trie),
       makevarlist(N,L),
       trie_intern(L,Trie),
       fail.
test_intern_1(_N):-
       trie_interned(L,1),
%       numbervars(L),
	length(L,Len),
       writeln(intern_length(Len)),
       fail.
test_intern_1(_N).

test_intern_2(N):- 
       new_trie(Trie),
       makevarlist(N,L),
       trie_intern(L,Trie,_Leaf,Skel),
%       functor(Skel,_T,Arity),
%       writeln(arity(Arity)),
       numbervars(Skel),
%       writeln(skel(Skel)),
       arg(500,Skel,Arg),
       writeln(test_intern_2_arg500(Arg)),
%       arg(Skel,750,Arg1),
%       writeln(test_intern_21(Arg1)),
       fail.
test_intern_2(_N).

